#define MAX_EVENTS 64
int epfd = 42;
int timeout_ms = 1000;
int ready_fds;
struct epoll_event ev_list[MAX_EVENTS];
sigset_t mask;

// Setup signal mask (signals to unblock during wait)
sigemptyset(&mask);
sigaddset(&mask, SIGHUP);
sigaddset(&mask, SIGUSR1);
// (These signals must be blocked in the thread's mask beforehand)

ready_fds = epoll_pwait(
    epfd,
    ev_list,
    MAX_EVENTS,
    timeout_ms,
    &mask
);
